package vn.iotstar.controller; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.PageRequest; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import vn.iotstar.entity.Category; import vn.iotstar.repository.CategoryRepository; @Controller @RequiredArgsConstructor public class CategoryController{final CategoryRepository cats;@GetMapping("/categories")String list(@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="0")int page,Model m){m.addAttribute("categories",cats.findByNameContainingIgnoreCase(q,PageRequest.of(Math.max(0,page),10)));return "categories/list";}@PostMapping("/categories")String add(@RequestParam String name){cats.save(new Category(name));return "redirect:/categories";}@PostMapping("/categories/{id}/delete")String del(@PathVariable Long id){cats.deleteById(id);return "redirect:/categories";}}
